<?php
require __DIR__.'/../app/bootstrap.php';require __DIR__.'/../app/admin_shell.php';security_headers();require_admin();$db=database();$state=admin_activity_resolution($db);$activity=$state['activity'];$id=$activity?(int)$activity['id']:0;$q=$db->prepare('SELECT i.*,a.admin_name,a.slug FROM interest_submissions i LEFT JOIN activities a ON a.id=i.activity_id'.($id?' WHERE i.activity_id=?':'').' ORDER BY i.id DESC');$q->execute($id?[$id]:[]);$rows=$q->fetchAll();admin_shell_start('responses','Respostas',$state);
?><section class="section-intro"><p><?= $id?'Respostas recebidas nesta atividade.':'Selecione uma atividade para ver as respostas.' ?></p><div class="admin-actions"><?php if($id&&$rows): ?><a href="/admin/export.php?activity=<?= $id ?>">Exportar CSV</a><?php endif; ?><span><?= count($rows) ?> <?= count($rows)===1?'resposta':'respostas' ?></span></div></section><section class="submission-list"><?php if(!$rows): ?><div class="admin-empty compact"><h2>Nenhuma resposta ainda</h2><p>Quando alguém enviar o formulário, ela aparecerá aqui.</p></div><?php endif; foreach($rows as $r):$p=json_decode($r['payload_json'],true)?:[];$detailId='submission-'.(int)$r['id'];?><article class="submission-card"><button class="submission-toggle" type="button" aria-expanded="false" aria-controls="<?= $detailId ?>"><span class="submission-summary"><span><strong><?= h($r['name']) ?></strong><small><?= h($r['email']) ?></small></span><small><?= h(date('d/m/Y · H:i',strtotime($r['created_at']))) ?></small></span></button><div class="submission-detail" id="<?= $detailId ?>" hidden><dl><?php foreach($p as $k=>$v):?><dt><?= h($k) ?></dt><dd><?= nl2br(h((string)$v)) ?></dd><?php endforeach;?></dl></div></article><?php endforeach;?></section><?php admin_shell_end();
